import { useEffect, useState } from 'react';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { Applicant } from '../../types/app.types';
import UnderlineHeading from '@/components/heading/UnderlineHeading';
import { Input } from '@/components/ui/input';
import SearchIcon from '@/components/icons/Search';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import AddIcon from '@/components/icons/AddIcon';
import AddAppDialog from './AddAppDialog';
import ApplicantCard from './ApplicantCard';
import ApplicationPreview from './ApplicationPreview';

const ApplicantsList = () => {
    const [data, setData] = useState<Applicant[]>([]);
    const [pageCount, setPageCount] = useState(0);
    const [totalCount, setTotalCount] = useState(0);
    const [isLoading, setIsLoading] = useState(false);
    const [pageIndex, setPageIndex] = useState(0);
    const [globalFilter, setGlobalFilter] = useState('');
    const [openAddPopup, setOpenAddPopup] = useState(false);
    const [openPreviewDialog, setOpenPreviewDialog] = useState(false);
    const [selectedApplicant, setSelectedApplicant] = useState<Applicant | null>(null);

    const fetchData = async () => {
        setIsLoading(true);

        try {
            const response = await apiGet({
                endpoint: endpoints.applicant.list,
                queryParams: { page: pageIndex + 1, search: globalFilter },
            });

            setData(response.data.data.data);
            setPageCount(Math.ceil(response.data.data.pagination.total / 10));
            setTotalCount(response.data.data.pagination.total);
        } catch {
            setData([]);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, [pageIndex, globalFilter]);

    const handleOpenPreview = (applicant: Applicant) => {
        setSelectedApplicant(applicant);
        setOpenPreviewDialog(true);
    };

    return (
        <>
            <AddAppDialog
                openAddPopup={openAddPopup}
                setOpenAddPopup={setOpenAddPopup}
                fetchData={fetchData}
            />
            <ApplicationPreview
                applicant={selectedApplicant}
                openPreviewDialog={openPreviewDialog}
                setOpenPreviewDialog={setOpenPreviewDialog}
            />
            <div className="mb-10 mt-4 rounded-lg border border-[#E8E7EA] shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A]">
                <div className="flex flex-col gap-4 p-3 sm:p-4 sm:flex-row sm:items-center sm:justify-between border-b border-[#E8E7EA]">
                    <UnderlineHeading text="قائمة المتقدمين" />
                    <div className="flex flex-wrap items-center gap-3">
                    <div className="flex flex-row items-center w-[280px] border border-white-blue-300 bg-white-blue-50 h-[36px] p-2 rounded-[6px]">
                            <Input
                                placeholder="ابحث باسم المتقدم"
                                value={globalFilter}
                                onChange={(event) => {
                                    setPageIndex(0);
                                    setGlobalFilter(event.target.value);
                                }}
                                className="text-white-blue-800 p-0 tracking-normal text-xs lg:text-sm lg:leading-[16.8px] border-none outline-none focus-visible:ring-0 placeholder:text-white-blue-800"
                            />
                            <button type="button" className="bg-transparent border-none">
                                <SearchIcon className="text-white-blue-800" />
                            </button>
                        </div>
                        <PrimaryButton
                            asChild
                            className="text-base px-[14px] xl:py-2 leading-5 font-semibold font-cairo tracking-normal"
                        >
                            <button type="button" onClick={() => setOpenAddPopup(true)}>
                                <AddIcon />
                                <p className="text-xs tracking-normal font-normal leading-[22.49px]">إضافة متقدم</p>
                            </button>
                        </PrimaryButton>
                        <PrimaryButton className="text-base px-[14px] xl:py-2 leading-5 font-semibold font-cairo tracking-normal">
                            تصدير
                        </PrimaryButton>
                    </div>
                </div>

                <div className="p-4">
                    {isLoading ? (
                        <div className="text-center py-8 text-sm text-white-blue-900">جاري التحميل...</div>
                    ) : data.length === 0 ? (
                        <div className="text-center py-8 text-sm text-white-blue-900">لا توجد بيانات متاحة</div>
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                            {data.map((applicant) => (
                                <ApplicantCard key={applicant.id} applicant={applicant} onClick={handleOpenPreview} />
                            ))}
                        </div>
                    )}
                </div>

                <div className="flex flex-col sm:flex-row items-center justify-between gap-3 px-4 pb-4 text-xs text-[#625E74]">
                    <p>
                        عرض {Math.min(pageIndex * 10 + 1, totalCount)} إلى {Math.min((pageIndex + 1) * 10, totalCount)}{' '}
                        من {totalCount}
                    </p>
                    <div className="flex items-center gap-2">
                        <button
                            type="button"
                            className="border rounded px-2 py-1 disabled:opacity-50"
                            disabled={pageIndex === 0}
                            onClick={() => setPageIndex((prev) => Math.max(prev - 1, 0))}
                        >
                            السابق
                        </button>
                        <span>
                            {pageIndex + 1} / {Math.max(pageCount, 1)}
                        </span>
                        <button
                            type="button"
                            className="border rounded px-2 py-1 disabled:opacity-50"
                            disabled={pageIndex + 1 >= pageCount}
                            onClick={() => setPageIndex((prev) => prev + 1)}
                        >
                            التالي
                        </button>
                    </div>
                </div>
            </div>
        </>
    );
};

export default ApplicantsList;
