import { Applicant } from '../../types/app.types';

interface ApplicantCardProps {
    applicant: Applicant;
    onClick: (applicant: Applicant) => void;
}

export default function ApplicantCard({ applicant, onClick }: ApplicantCardProps) {
    const splitSkills = (value: string) =>
        value
            .split(/[\r\n,]+|\s+/)
            .map((s) => s.trim())
            .filter(Boolean);

    const skills = Array.isArray(applicant.skills)
        ? applicant.skills
        : typeof applicant.skills === 'string'
          ? splitSkills(applicant.skills)
          : (applicant.skills_text
                ? splitSkills(applicant.skills_text)
                : []);

    return (
        <button
            type="button"
            onClick={() => onClick(applicant)}
            className="w-full text-right border border-[#E8E7EA] rounded-xl p-4 bg-white shadow-sm transition hover:shadow-md"
        >
            <div className="flex items-center justify-between">
                <h3 className="text-sm font-semibold text-primery-blue-900">{applicant.name}</h3>
                <span className="text-[11px] px-2 py-0.5 rounded-md bg-[#EDF8F2] text-[#1D9D62]">
                    {applicant.pipeline_stage ?? 'مُفعل'}
                </span>
            </div>
            <p className="text-xs text-[#625E74] mt-1">
                {applicant.job?.title ?? applicant.job?.name ?? applicant.job_title ?? '-'}
            </p>
            <p className="text-xs text-[#90868C] mt-1">
                {applicant.experience_years != null ? `${applicant.experience_years} سنوات خبرة` : ''}
            </p>
            <div className="flex flex-wrap gap-1.5 mt-3">
                {skills.slice(0, 4).map((skill) => (
                    <span
                        key={`${applicant.id}-${skill}`}
                        className="text-[10px] px-2 py-0.5 rounded bg-[#EEF3FF] text-[#4361EE]"
                    >
                        {skill}
                    </span>
                ))}
            </div>
        </button>
    );
}
